import java.util.*;import com.alibaba.druid.sql.SQLUtils;import com.alibaba.druid.util.JdbcConstants;import webridge.wbridge.sql.ast.SQLAstVisitor;
public class BindTypeTest{public static void main(String[]a){String sql="SELECT CASE WHEN ?=? THEN 0 ELSE 1 END AS length";SQLAstVisitor v=new SQLAstVisitor(sql);v.setRecordedParameterJavaTypes(Arrays.asList("java/lang/String","java/lang/String"));SQLUtils.parseSingleStatement(sql,JdbcConstants.MYSQL).accept(v);if(v.getArgTypeLst().size()!=2||!v.getArgTypeLst().get(0).toString().equals("VARCHAR(512)"))throw new AssertionError();boolean rejected=false;try{SQLAstVisitor unknown=new SQLAstVisitor(sql);SQLUtils.parseSingleStatement(sql,JdbcConstants.MYSQL).accept(unknown);}catch(IllegalArgumentException expected){rejected=true;}if(!rejected)throw new AssertionError("Untyped ambiguous parameters must remain rejected");System.out.println("PASS: recorded String metadata resolves two ambiguous binds; absent metadata still rejects ambiguity");}}
